//! Internationalization for NetTrap reports.
//!
//! This module provides translation support for 30+ languages in NBI report generation.
//!
//! **Note:** The large translation table below is auto-generated. The file is intentionally
//! large (~1050 lines) as it contains all UI strings for HTML reports in multiple languages.
//! This is not a "God Object" - it's a static data file similar to a JSON/resource bundle.
//!
//! # File Size Justification
//!
//! This file is ~1050 lines because it contains:
//! - 30+ languages × ~30 translation keys = ~900 entries
//!
//! Alternative approaches (JSON/TOML files) were considered but this approach:
//! - Avoids runtime file I/O
//! - Provides compile-time validation
//! - Has zero-cost access via static LazyLock

use std::collections::HashMap;
use std::sync::LazyLock;

/// Get translation for a key in the specified language. Falls back to English.
pub fn t<'a>(key: &'a str, lang: &str) -> &'a str {
    TRANSLATIONS
        .get(lang)
        .and_then(|map| map.get(key))
        .or_else(|| TRANSLATIONS.get("en").and_then(|map| map.get(key)))
        .copied()
        .unwrap_or(key)
}

