#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_english_fallback() {
        assert_eq!(t("total_events", "en"), "Total Events");
    }

    #[test]
    fn test_spanish_translation() {
        assert_eq!(t("total_events", "es"), "Total de Eventos");
    }

    #[test]
    fn test_unknown_language_falls_back_to_english() {
        assert_eq!(t("total_events", "xx"), "Total Events");
    }

    #[test]
    fn test_unknown_key_returns_key() {
        assert_eq!(t("nonexistent_key", "en"), "nonexistent_key");
    }

    #[test]
    fn test_all_supported_languages_have_report_title() {
        for (code, _name) in SUPPORTED_LANGUAGES {
            let title = t("report_title", code);
            assert!(
                title.contains("NetTrap"),
                "Language {} missing report_title",
                code
            );
        }
    }

    #[test]
    fn test_supported_languages_count() {
        assert!(
            SUPPORTED_LANGUAGES.len() >= 32,
            "Expected 32+ languages, got {}",
            SUPPORTED_LANGUAGES.len()
        );
    }
}
